INSERT INTO public.topics (id, term_id, title, order_no) VALUES
('b0000000-0000-0000-0000-000000000109', 'a0000000-0000-0000-0000-000000000001', 'Biodiversity & Ecosystems', 9),
('b0000000-0000-0000-0000-000000000110', 'a0000000-0000-0000-0000-000000000001', 'Heredity & Genetics', 10)
INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, bloom_taxonomy, image_url, is_active) VALUES('b0000000-0000-0000-0000-000000000101', 2, 'pre_test', 'Rotting tomatoes is a chemical change because new substances are formed.', 'True', 'False', '', '', 'True', 'Decomposition reactions form entirely new chemical substances.', 'UNDERSTANDING', true),
('b0000000-0000-0000-0000-000000000101', 2, 'pre_test', 'Crushing chunks of ice is a chemical change because its shape changes.', 'True', 'False', '', '', 'False', 'Crushing changes physical dimensions only; composition remains H2O.', 'APPLYING', 'assets/illustrations/term1_tf/t1_tf_q1.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'pre_test', 'A chemical change produces one or more new substances with different properties.', 'True', 'False', '', '', 'True', 'Chemical bonds break and reform to yield novel molecular structures.', 'REMEMBERING', 'assets/illustrations/term1_tf/t1_tf_q2.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'pre_test', 'Photosynthesis is a physical change because plants only absorb sunlight.', 'True', 'False', '', '', 'False', 'Photosynthesis is a complex chemical conversion producing glucose.', 'ANALYZING', 'assets/illustrations/term1_tf/t1_tf_q3.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'pre_test', 'Gas bubbles produced when vinegar reacts with baking soda indicate a chemical reaction.', 'True', 'False', '', '', 'True', 'Carbon dioxide gas bubbles form as a primary product.', 'ANALYZING', 'assets/illustrations/term1_tf/t1_tf_q4.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'pre_test', 'Curdling of milk is considered primary evidence of gas formation.', 'True', 'False', '', '', 'False', 'Curdling is solid protein precipitation, not gas evolution.', 'UNDERSTANDING', 'assets/illustrations/term1_tf/t1_tf_q5.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'pre_test', 'If a container becomes hot after quicklime mixes with water, a reaction occurred.', 'True', 'False', '', '', 'True', 'Exothermic reactions release thermal heat energy to surroundings.', 'ANALYZING', 'assets/illustrations/term1_tf/t1_tf_q6.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'pre_test', 'Simply cutting paper into pieces is evidence that a chemical reaction occurred.', 'True', 'False', '', '', 'False', 'Cutting alters size/shape only, keeping chemical composition intact.', 'APPLYING', 'assets/illustrations/term1_tf/t1_tf_q7.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'pre_test', 'When two clear liquids produce an insoluble solid, a precipitate has formed.', 'True', 'False', '', '', 'True', 'Precipitates are insoluble solid products settling out of solution.', 'REMEMBERING', 'assets/illustrations/term1_tf/t1_tf_q8.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'pre_test', 'Reactants in a chemical equation are conventionally written on the right side.', 'True', 'False', '', '', 'False', 'Reactants are always written on the left side of the reaction arrow.', 'REMEMBERING', 'assets/illustrations/term1_tf/t1_tf_q9.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'pre_test', 'Products are the newly formed substances resulting from a chemical reaction.', 'True', 'False', '', '', 'True', 'Products appear on the right side of the reaction arrow.', 'REMEMBERING', 'assets/illustrations/term1_tf/t1_tf_q10.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'pre_test', 'The symbol (aq) designates that a chemical species is in the gaseous state.', 'True', 'False', '', '', 'False', '(aq) specifies an aqueous solution dissolved in water.', 'UNDERSTANDING', 'assets/illustrations/term1_tf/t1_tf_q11.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'pre_test', 'The delta symbol (Δ) above a reaction arrow signifies thermal energy input.', 'True', 'False', '', '', 'True', 'Delta denotes that heating is supplied to drive the reaction.', 'UNDERSTANDING', 'assets/illustrations/term1_tf/t1_tf_q12.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'pre_test', 'A downward pointing arrow (↓) beside a product denotes gas evolution.', 'True', 'False', '', '', 'False', 'A downward arrow indicates a solid precipitate settling out.', 'ANALYZING', 'assets/illustrations/term1_tf/t1_tf_q13.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'pre_test', 'The plus sign (+) in chemical equations translates to "reacts with" or "and".', 'True', 'False', '', '', 'True', 'It separates multiple reactants or products in the equation.', 'REMEMBERING', 'assets/illustrations/term1_tf/t1_tf_q14.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'pre_test', 'A combination reaction follows the general formula A + B → AB.', 'True', 'False', '', '', 'True', 'Two or more reactants merge into a single product compound.', 'UNDERSTANDING', 'assets/illustrations/term1_tf/t1_tf_q15.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'pre_test', 'The reaction 2Na + Cl ₂ → 2NaCl is categorized as a decomposition reaction.', 'True', 'False', '', '', 'False', 'This is a combination (synthesis) reaction forming one salt.', 'ANALYZING', 'assets/illustrations/term1_tf/t1_tf_q16.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'pre_test', 'The thermal breakdown CaCO ₃ → CaO + CO ₂ is a decomposition reaction.', 'True', 'False', '', '', 'True', 'One complex reactant splits into two or more simpler products.', 'UNDERSTANDING', 'assets/illustrations/term1_tf/t1_tf_q17.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'pre_test', 'The general equation AB → A + B represents a standard combination reaction.', 'True', 'False', '', '', 'False', 'This formula represents decomposition, not combination.', 'APPLYING', 'assets/illustrations/term1_tf/t1_tf_q18.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'pre_test', 'In a single displacement reaction, an uncombined element displaces another in a compound.', 'True', 'False', '', '', 'True', 'A + BC → AC + B typifies single replacement mechanics.', 'REMEMBERING', 'assets/illustrations/term1_tf/t1_tf_q19.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Double displacement reactions involve single element replacement.', 'True', 'False', '', '', 'False', 'They involve mutual exchange of ions between two compounds.', 'UNDERSTANDING', 'assets/illustrations/term1_tf/t1_tf_q20.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'AgNO ₃ + NaCl → AgCl + NaNO ₃ is a double displacement reaction.', 'True', 'False', '', '', 'True', 'The silver and sodium cations exchange anions to form AgCl precipitate.', 'APPLYING', 'assets/illustrations/term1_tf/t1_tf_q21.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Oxygen gas is always a reactant in combustion reactions.', 'True', 'False', '', '', 'True', 'Combustion requires an oxidizing agent, typically oxygen.', 'REMEMBERING', 'assets/illustrations/term1_tf/t1_tf_q22.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Combustion of hydrocarbons always produces salt and water.', 'True', 'False', '', '', 'False', 'They produce carbon dioxide and water vapor, not salt.', 'ANALYZING', 'assets/illustrations/term1_tf/t1_tf_q23.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Neutralization reactions produce salt and water.', 'True', 'False', '', '', 'True', 'Acids reacting with bases neutralize to form ionic salts and water.', 'REMEMBERING', 'assets/illustrations/term1_tf/t1_tf_q24.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Neutralization is a special type of combination reaction.', 'True', 'False', '', '', 'False', 'It is classified as a double displacement (acid-base) reaction.', 'UNDERSTANDING', 'assets/illustrations/term1_tf/t1_tf_q25.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Melting wax is an example of a physical change.', 'True', 'False', '', '', 'True', 'Phase changes alter state without changing molecular structure.', 'UNDERSTANDING', 'assets/illustrations/term1_tf/t1_tf_q26.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Salt dissolving in water is evidence of a chemical reaction.', 'True', 'False', '', '', 'False', 'Dissolution is a physical process; salt can be recovered via evaporation.', 'ANALYZING', 'assets/illustrations/term1_tf/t1_tf_q27.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'In Mg + O ₂ → MgO, magnesium oxide is the product.', 'True', 'False', '', '', 'True', 'Products are located on the right side of the reaction arrow.', 'REMEMBERING', 'assets/illustrations/term1_tf/t1_tf_q28.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Fuel reacting with oxygen to yield CO ₂ and H ₂ O is combustion.', 'True', 'False', '', '', 'True', 'This describes complete hydrocarbon combustion.', 'REMEMBERING', 'assets/illustrations/term1_tf/t1_tf_q29.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'The arrow in a chemical equation means yields or produces.', 'True', 'False', '', '', 'True', 'The reaction arrow separates reactants from produced products.', 'REMEMBERING', 'assets/illustrations/term1_tf/t1_tf_q30.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'The reaction 2H ₂ O ₂ → 2H ₂ O + O ₂ is a synthesis reaction.', 'True', 'False', '', '', 'False', 'Hydrogen peroxide breaks down, making it decomposition.', 'ANALYZING', 'assets/illustrations/term1_tf/t1_tf_q31.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Double displacement reactions involve ion exchange between compounds.', 'True', 'False', '', '', 'True', 'Positive and negative ions switch pairing partners.', 'UNDERSTANDING', 'assets/illustrations/term1_tf/t1_tf_q32.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Iron reacting with sulfur to form iron sulfide is synthesis.', 'True', 'False', '', '', 'True', 'Two elemental reactants combine to form one compound.', 'APPLYING', 'assets/illustrations/term1_tf/t1_tf_q33.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'An upward arrow beside a product indicates that a solid has formed.', 'True', 'False', '', '', 'False', 'An upward arrow denotes gas evolution.', 'ANALYZING', 'assets/illustrations/term1_tf/t1_tf_q34.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Oxidation involves the loss of electrons by a substance.', 'True', 'False', '', '', 'True', 'Remember OIL RIG (Oxidation Is Loss, Reduction Is Gain).', 'REMEMBERING', 'assets/illustrations/term1_tf/t1_tf_q35.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Reduction is defined as the loss of hydrogen atoms.', 'True', 'False', '', '', 'False', 'Reduction is the gain of electrons or gain of hydrogen.', 'UNDERSTANDING', 'assets/illustrations/term1_tf/t1_tf_q36.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Corrosion of metals is an unwanted chemical change.', 'True', 'False', '', '', 'True', 'Oxidation degrades structural metals over time.', 'UNDERSTANDING', 'assets/illustrations/term1_tf/t1_tf_q37.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Endothermic chemical changes release thermal energy.', 'True', 'False', '', '', 'False', 'Endothermic changes absorb thermal energy from surroundings.', 'REMEMBERING', 'assets/illustrations/term1_tf/t1_tf_q38.svg', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Total mass remains constant during any chemical change.', 'True', 'False', '', '', 'True', 'This upholds the fundamental Law of Conservation of Mass.', 'EVALUATING', 'assets/illustrations/term1_tf/t1_tf_q39.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'pre_test', 'All acids taste sour and turn blue litmus paper red.', 'True', 'False', '', '', 'True', 'Sour taste and litmus color change are classic acid traits.', 'REMEMBERING', 'assets/illustrations/term1_tf/t2_tf_q1.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'pre_test', 'Bases turn blue litmus paper red.', 'True', 'False', '', '', 'False', 'Bases turn red litmus paper blue.', 'UNDERSTANDING', 'assets/illustrations/term1_tf/t2_tf_q2.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'pre_test', 'Pure water has a neutral pH of 7.', 'True', 'False', '', '', 'True', 'pH 7 represents equal hydrogen and hydroxide ion concentrations.', 'REMEMBERING', 'assets/illustrations/term1_tf/t2_tf_q3.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'pre_test', 'Phenolphthalein is pink in acidic solutions.', 'True', 'False', '', '', 'False', 'Phenolphthalein is colorless in acids and turns pink in bases.', 'ANALYZING', 'assets/illustrations/term1_tf/t2_tf_q4.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'pre_test', 'Acids release hydrogen ions (H ⁺ ) when dissolved in water.', 'True', 'False', '', '', 'True', 'Arrhenius acids dissociate to yield hydrogen ions.', 'REMEMBERING', 'assets/illustrations/term1_tf/t2_tf_q5.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'pre_test', 'Bases release hydrogen ions in water solution.', 'True', 'False', '', '', 'False', 'Bases release hydroxide ions (OH ⁻ ).', 'UNDERSTANDING', 'assets/illustrations/term1_tf/t2_tf_q6.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'pre_test', 'Sodium chloride (NaCl) is common table salt.', 'True', 'False', '', '', 'True', 'NaCl is a neutral ionic salt.', 'REMEMBERING', 'assets/illustrations/term1_tf/t2_tf_q7.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'pre_test', 'Stomach acid formula is H ₂ SO ₄ .', 'True', 'False', '', '', 'False', 'Stomach gastric acid is hydrochloric acid (HCl).', 'APPLYING', 'assets/illustrations/term1_tf/t2_tf_q8.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'pre_test', 'Sodium hydroxide (NaOH) is a strong base known as lye.', 'True', 'False', '', '', 'True', 'NaOH is caustic soda or lye.', 'REMEMBERING', 'assets/illustrations/term1_tf/t2_tf_q9.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'pre_test', 'Methyl orange is yellow in acids and red in bases.', 'True', 'False', '', '', 'False', 'Methyl orange is red in acids and yellow in bases.', 'UNDERSTANDING', 'assets/illustrations/term1_tf/t2_tf_q10.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'pre_test', 'Turmeric is a natural acid-base indicator.', 'True', 'False', '', '', 'True', 'Turmeric changes color in basic solutions.', 'REMEMBERING', 'assets/illustrations/term1_tf/t2_tf_q11.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'pre_test', 'A solution with pH 7 is acidic.', 'True', 'False', '', '', 'False', 'pH 7 is strictly neutral.', 'REMEMBERING', 'assets/illustrations/term1_tf/t2_tf_q12.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'pre_test', 'Vinegar contains acetic acid.', 'True', 'False', '', '', 'True', 'Acetic acid gives vinegar its sour flavor.', 'REMEMBERING', 'assets/illustrations/term1_tf/t2_tf_q13.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'pre_test', 'Milk of magnesia contains sodium hydroxide.', 'True', 'False', '', '', 'False', 'It contains magnesium hydroxide, Mg(OH) ₂ .', 'APPLYING', 'assets/illustrations/term1_tf/t2_tf_q14.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'pre_test', 'Blue litmus paper remains blue in a basic solution.', 'True', 'False', '', '', 'True', 'Bases do not alter blue litmus paper color.', 'UNDERSTANDING', 'assets/illustrations/term1_tf/t2_tf_q15.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'pre_test', 'Hydrochloric acid, vinegar, and calamansi are acids.', 'True', 'False', '', '', 'True', 'All exhibit characteristic acid properties.', 'REMEMBERING', 'assets/illustrations/term1_tf/t2_tf_q16.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'pre_test', 'Sodium hydroxide and bleach are bases.', 'True', 'False', '', '', 'True', 'They act as alkaline bases.', 'REMEMBERING', 'assets/illustrations/term1_tf/t2_tf_q17.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'pre_test', 'Antacids relieve hyperacidity because they are weak acids.', 'True', 'False', '', '', 'False', 'Antacids are mild bases that neutralize stomach acid.', 'UNDERSTANDING', 'assets/illustrations/term1_tf/t2_tf_q18.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'pre_test', 'A solution with a pH of 4 is acidic.', 'True', 'False', '', '', 'True', 'Any pH value below 7 is acidic.', 'REMEMBERING', 'assets/illustrations/term1_tf/t2_tf_q19.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'pre_test', 'A solution with a pH of 11 is acidic.', 'True', 'False', '', '', 'False', 'pH values above 7 are basic or alkaline.', 'UNDERSTANDING', 'assets/illustrations/term1_tf/t2_tf_q20.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Among pH 1, 3, and 6, pH 6 is the weakest acid.', 'True', 'False', '', '', 'True', 'It is closest to neutral pH 7.', 'ANALYZING', 'assets/illustrations/term1_tf/t2_tf_q21.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Neutralization produces salt and water from acid and base.', 'True', 'False', '', '', 'True', 'This is the standard neutralization reaction formula.', 'REMEMBERING', 'assets/illustrations/term1_tf/t2_tf_q22.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Turmeric turns reddish-brown in a base like soap.', 'True', 'False', '', '', 'True', 'This color change indicates basic conditions.', 'APPLYING', 'assets/illustrations/term1_tf/t2_tf_q23.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Onion and vanilla are synthetic indicators.', 'True', 'False', '', '', 'False', 'They are olfactory indicators changing scent.', 'UNDERSTANDING', 'assets/illustrations/term1_tf/t2_tf_q24.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Tooth enamel dissolves when mouth pH drops below 5.5.', 'True', 'False', '', '', 'True', 'Low pH accelerates tooth decay.', 'ANALYZING', 'assets/illustrations/term1_tf/t2_tf_q25.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Sodium carbonate forms an acidic solution in water.', 'True', 'False', '', '', 'False', 'It forms a basic alkaline solution.', 'ANALYZING', 'assets/illustrations/term1_tf/t2_tf_q26.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Ammonium chloride forms an acidic solution in water.', 'True', 'False', '', '', 'True', 'NH ₄ Cl is an acidic salt.', 'APPLYING', 'assets/illustrations/term1_tf/t2_tf_q27.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Dry HCl gas changes dry blue litmus paper red immediately.', 'True', 'False', '', '', 'False', 'Water is required for HCl to release hydrogen ions.', 'ANALYZING', 'assets/illustrations/term1_tf/t2_tf_q28.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Each pH unit represents a tenfold change in [H ⁺ ].', 'True', 'False', '', '', 'True', 'The pH scale is logarithmic.', 'REMEMBERING', 'assets/illustrations/term1_tf/t2_tf_q29.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'In order pH 2, 6, 7, 9, 12, pH 12 is strongest acid.', 'True', 'False', '', '', 'False', 'pH 12 is the strongest base.', 'UNDERSTANDING', 'assets/illustrations/term1_tf/t2_tf_q30.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'NaCl from strong acid and strong base is neutral.', 'True', 'False', '', '', 'True', 'HCl and NaOH neutralize completely.', 'UNDERSTANDING', 'assets/illustrations/term1_tf/t2_tf_q31.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Acid and base solutions conduct electricity via mobile ions.', 'True', 'False', '', '', 'True', 'Electrolytes permit current flow.', 'REMEMBERING', 'assets/illustrations/term1_tf/t2_tf_q32.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'When diluting acid, pour water into concentrated acid.', 'True', 'False', '', '', 'False', 'Always add acid to water to prevent dangerous splattering.', 'APPLYING', 'assets/illustrations/term1_tf/t2_tf_q33.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Acetic acid is the weak acid present in vinegar.', 'True', 'False', '', '', 'True', 'It imparts vinegar''s characteristics.', 'REMEMBERING', 'assets/illustrations/term1_tf/t2_tf_q34.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Baking soda reacts with acids to release oxygen gas.', 'True', 'False', '', '', 'False', 'It releases carbon dioxide gas.', 'UNDERSTANDING', 'assets/illustrations/term1_tf/t2_tf_q35.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Buffer solutions resist drastic changes in pH.', 'True', 'False', '', '', 'True', 'Buffers stabilize pH levels effectively.', 'REMEMBERING', 'assets/illustrations/term1_tf/t2_tf_q36.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'All alkalis are water-soluble bases.', 'True', 'False', '', '', 'True', 'Alkalis form hydroxide ions in aqueous solution.', 'REMEMBERING', 'assets/illustrations/term1_tf/t2_tf_q37.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Titration determines unknown concentration using neutralization.', 'True', 'False', '', '', 'True', 'Stoichiometric endpoints reveal concentration.', 'APPLYING', 'assets/illustrations/term1_tf/t2_tf_q38.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Unpolluted rainwater is strictly acidic with pH 2.', 'True', 'False', '', '', 'False', 'Natural rainwater is slightly acidic around pH 5.6 due to dissolved CO ₂ .', 'UNDERSTANDING', 'assets/illustrations/term1_tf/t2_tf_q39.svg', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Hydrolysis of salts can result in acidic or basic solutions.', 'True', 'False', '', '', 'True', 'Salt ions react with water depending on parent acid/base strength.', 'EVALUATING', 'assets/illustrations/term1_tf/t2_tf_q40.svg', true),
('b0000000-0000-0000-0000-000000000104', 2, 'pre_test', 'Reactants are written on the left side of a chemical equation.', 'True', 'False', '', '', 'True', 'Starting materials occupy the left side.', 'REMEMBERING', 'assets/illustrations/term1_tf/t3_tf_q1.svg', true),
('b0000000-0000-0000-0000-000000000104', 2, 'pre_test', 'Products are found on the left side of the reaction arrow.', 'True', 'False', '', '', 'False', 'Products are written on the right side.', 'UNDERSTANDING', 'assets/illustrations/term1_tf/t3_tf_q2.svg', true),
('b0000000-0000-0000-0000-000000000104', 2, 'pre_test', 'The symbol (aq) means dissolved in water.', 'True', 'False', '', '', 'True', 'Aqueous solutions are water-based.', 'REMEMBERING', 'assets/illustrations/term1_tf/t3_tf_q3.svg', true),
('b0000000-0000-0000-0000-000000000104', 2, 'pre_test', 'The symbol (s) represents a gas.', 'True', 'False', '', '', 'False', '(s) stands for solid state.', 'REMEMBERING', 'assets/illustrations/term1_tf/t3_tf_q4.svg', true),
('b0000000-0000-0000-0000-000000000104', 2, 'pre_test', 'The symbol (g) indicates a gaseous state.', 'True', 'False', '', '', 'True', '(g) denotes gases.', 'REMEMBERING', 'assets/illustrations/term1_tf/t3_tf_q5.svg', true),
('b0000000-0000-0000-0000-000000000104', 2, 'pre_test', 'Mass can be created during a chemical reaction.', 'True', 'False', '', '', 'False', 'Mass is conserved, neither created nor destroyed.', 'UNDERSTANDING', 'assets/illustrations/term1_tf/t3_tf_q6.svg', true),
('b0000000-0000-0000-0000-000000000104', 2, 'pre_test', 'The arrow means yields or produces.', 'True', 'False', '', '', 'True', 'It shows reaction direction.', 'REMEMBERING', 'assets/illustrations/term1_tf/t3_tf_q7.svg', true),
('b0000000-0000-0000-0000-000000000104', 2, 'pre_test', 'Plus sign between reactants means reacts with or and.', 'True', 'False', '', '', 'True', 'Combines reactants or products.', 'REMEMBERING', 'assets/illustrations/term1_tf/t3_tf_q8.svg', true),
('b0000000-0000-0000-0000-000000000104', 2, 'pre_test', 'A balanced equation has equal atoms on both sides.', 'True', 'False', '', '', 'True', 'Conforms to conservation laws.', 'REMEMBERING', 'assets/illustrations/term1_tf/t3_tf_q9.svg', true),
